CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE user_role AS ENUM ('attendee','organizer','administrator','gate_operator');
CREATE TABLE users(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,email text NOT NULL UNIQUE,password_hash text NOT NULL,role user_role NOT NULL DEFAULT 'attendee',status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','suspended','deleted')),organizer_verified boolean NOT NULL DEFAULT false,last_login_at timestamptz,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refresh_tokens(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users ON DELETE CASCADE,token_hash text NOT NULL UNIQUE,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE venues(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,address text NOT NULL,city text NOT NULL,capacity integer NOT NULL CHECK(capacity>0),created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE events(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),organizer_id uuid NOT NULL REFERENCES users,venue_id uuid REFERENCES venues,title text NOT NULL,description text NOT NULL DEFAULT '',category text NOT NULL DEFAULT '',starts_at timestamptz NOT NULL,ends_at timestamptz NOT NULL,currency char(3) NOT NULL DEFAULT 'INR',capacity integer NOT NULL CHECK(capacity>0),resale_limit_percent integer NOT NULL DEFAULT 100 CHECK(resale_limit_percent BETWEEN 0 AND 500),status text NOT NULL DEFAULT 'draft' CHECK(status IN ('draft','published','cancelled','completed')),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),CHECK(ends_at>starts_at));
CREATE INDEX events_public_idx ON events(status,starts_at);
CREATE TABLE ticket_types(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),event_id uuid NOT NULL REFERENCES events ON DELETE CASCADE,name text NOT NULL,description text NOT NULL DEFAULT '',price_minor bigint NOT NULL CHECK(price_minor>=0),currency char(3) NOT NULL DEFAULT 'INR',quantity_total integer NOT NULL CHECK(quantity_total>0),quantity_sold integer NOT NULL DEFAULT 0,quantity_reserved integer NOT NULL DEFAULT 0,per_user_limit integer NOT NULL DEFAULT 8,sales_start timestamptz,sales_end timestamptz,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(event_id,name),CHECK(quantity_sold+quantity_reserved<=quantity_total));
CREATE TABLE bookings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,event_id uuid NOT NULL REFERENCES events,status text NOT NULL CHECK(status IN ('pending','paid','failed','cancelled','refunded')),total_minor bigint NOT NULL CHECK(total_minor>=0),currency char(3) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),paid_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX bookings_user_created_idx ON bookings(user_id,created_at DESC);
CREATE TABLE booking_items(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES bookings ON DELETE CASCADE,ticket_type_id uuid NOT NULL REFERENCES ticket_types,quantity integer NOT NULL CHECK(quantity>0),unit_price_minor bigint NOT NULL CHECK(unit_price_minor>=0));
CREATE TABLE payments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL UNIQUE REFERENCES bookings,provider text NOT NULL DEFAULT 'razorpay',provider_order_id text UNIQUE,provider_payment_id text UNIQUE,status text NOT NULL CHECK(status IN ('created','captured','failed','refunded')),amount_minor bigint NOT NULL,currency char(3) NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tickets(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),booking_id uuid NOT NULL REFERENCES bookings,ticket_type_id uuid NOT NULL REFERENCES ticket_types,owner_id uuid NOT NULL REFERENCES users,ticket_hash text NOT NULL UNIQUE,qr_token_hash text NOT NULL UNIQUE,status text NOT NULL CHECK(status IN ('pending','active','transferred','redeemed','refunded','cancelled')),onchain_id text,issued_at timestamptz NOT NULL DEFAULT now(),redeemed_at timestamptz,redeemed_device_id uuid);
CREATE INDEX tickets_owner_idx ON tickets(owner_id,status);
CREATE TABLE refunds(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),payment_id uuid NOT NULL REFERENCES payments,provider_refund_id text UNIQUE,amount_minor bigint NOT NULL,status text NOT NULL,reason text,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE resale_listings(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL UNIQUE REFERENCES tickets, seller_id uuid NOT NULL REFERENCES users,price_minor bigint NOT NULL CHECK(price_minor>=0),status text NOT NULL CHECK(status IN ('listed','sold','cancelled')),created_at timestamptz NOT NULL DEFAULT now(),sold_at timestamptz);
CREATE TABLE ticket_transfers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid NOT NULL REFERENCES tickets,from_user_id uuid NOT NULL REFERENCES users,to_user_id uuid NOT NULL REFERENCES users,listing_id uuid REFERENCES resale_listings,price_minor bigint,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE blockchain_transactions(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),ticket_id uuid REFERENCES tickets,operation text NOT NULL,tx_hash text UNIQUE,status text NOT NULL CHECK(status IN ('queued','submitted','confirmed','failed')),attempts integer NOT NULL DEFAULT 0,last_error text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE gate_devices(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,event_id uuid REFERENCES events,api_key_hash text NOT NULL UNIQUE,status text NOT NULL DEFAULT 'active' CHECK(status IN ('active','online','offline','revoked')),last_seen_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE tickets ADD CONSTRAINT tickets_redeemed_device_fk FOREIGN KEY(redeemed_device_id) REFERENCES gate_devices;
CREATE TABLE gate_scans(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),device_id uuid NOT NULL REFERENCES gate_devices,ticket_id uuid REFERENCES tickets,event_id uuid REFERENCES events,scan_id text NOT NULL,result text NOT NULL,reason text NOT NULL,scanned_at timestamptz NOT NULL DEFAULT now(),UNIQUE(device_id,scan_id));
CREATE TABLE iot_readings(id bigserial PRIMARY KEY,device_id uuid NOT NULL REFERENCES gate_devices,event_id uuid REFERENCES events,ir_state text,distance_cm numeric(8,2),servo_angle integer CHECK(servo_angle BETWEEN 0 AND 180),payload jsonb NOT NULL DEFAULT '{}',recorded_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,channel text NOT NULL,status text NOT NULL DEFAULT 'queued',template text NOT NULL,payload jsonb NOT NULL DEFAULT '{}',sent_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE audit_logs(id bigserial PRIMARY KEY,actor_type text NOT NULL,actor_id uuid,action text NOT NULL,entity_type text NOT NULL,entity_id uuid,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE idempotency_keys(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL REFERENCES users,key text NOT NULL,response jsonb NOT NULL,expires_at timestamptz NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(user_id,key));
